mapper.select:
SELECT tab.*, ( SELECT max(lcr_temp.due_date) FROM lon_contract_repayment lcr_temp WHERE lcr_temp.times < tab.times AND lcr_temp.contract_id = tab.CONTRACT_ID AND lcr_temp.withdraw_id = tab.WITHDRAW_ID and lcr_temp.cf_item=302 ) AS repayment_date_from -- 获取上一期利息的due_date FROM ( SELECT glcfc.COMPANY_ID, glcfc.CONTRACT_ID, glcfc.DAYS, glcfc.END_DATE, glcfc.FINANCE_COST, glcfc.FINANCE_COST_ID, glcfc.GLD_CASHFLOW_ID, glcfc.PERIOD_NAME, glcfc.POST_FLAG, glcfc.REPAYMENT_ID, glcfc.SOURCE_ID, glcfc.SOURCE_TYPE, glcfc.START_DATE, glcfc.WITHDRAW_ID, lc.contract_number, lc.contract_name, lcw.withdraw_number, lcr.times, lcr.due_date AS repayment_date_to, lcw.due_amount AS withdraw_due_amount, lcq.loan_rate, lcr.due_amount AS repayment_due_amount FROM gld_lon_contract_fin_cost glcfc, lon_contract lc, lon_contract_quotation lcq, lon_contract_withdraw lcw, lon_contract_repayment lcr
,gld_period_status gps
WHERE glcfc.CONTRACT_ID = lc.contract_id AND lcq.contract_id = glcfc.CONTRACT_ID AND lcw.withdraw_id = glcfc.WITHDRAW_ID AND lcr.repayment_id = glcfc.REPAYMENT_ID AND glcfc.COMPANY_ID = #{companyId} AND glcfc.FINANCE_COST != 0
AND gps.PERIOD_NAME = glcfc.PERIOD_NAME AND gps.STATUS = 'OPEN'
) tab
tab.FINANCE_COST_ID = #{financeCostId}
AND tab.contract_number >= #{contractNumberFrom}
AND tab.contract_number <= #{contractNumberTo}
AND tab.POST_FLAG = #{postFlag}
AND tab.PERIOD_NAME >= #{periodNameFrom}
AND tab.PERIOD_NAME <= #{periodNameTo}
ORDER BY tab.CONTRACT_ID,tab.START_DATE

SELECT SUM(tab.FINANCE_COST) AS FINANCE_COST_SUM FROM ( SELECT glcfc.COMPANY_ID, glcfc.CONTRACT_ID, glcfc.DAYS, glcfc.END_DATE, glcfc.FINANCE_COST, glcfc.FINANCE_COST_ID, glcfc.GLD_CASHFLOW_ID, glcfc.PERIOD_NAME, glcfc.POST_FLAG, glcfc.REPAYMENT_ID, glcfc.SOURCE_ID, glcfc.SOURCE_TYPE, glcfc.START_DATE, glcfc.WITHDRAW_ID, lc.contract_number, lc.contract_name, lcw.withdraw_number, lcr.times, lcr.due_date AS repayment_date_to, lcw.due_amount AS withdraw_due_amount, lcq.loan_rate, lcr.due_amount AS repayment_due_amount FROM gld_lon_contract_fin_cost glcfc, lon_contract lc, lon_contract_quotation lcq, lon_contract_withdraw lcw, lon_contract_repayment lcr WHERE glcfc.CONTRACT_ID = lc.contract_id AND lcq.contract_id = glcfc.CONTRACT_ID AND lcw.withdraw_id = glcfc.WITHDRAW_ID AND lcr.repayment_id = glcfc.REPAYMENT_ID ) tab
tab.FINANCE_COST_ID = #{financeCostId}
AND tab.contract_number >= #{contractNumberFrom}
AND tab.contract_number <= #{contractNumberTo}
AND tab.POST_FLAG = #{postFlag}
AND tab.PERIOD_NAME >= #{periodNameFrom}
AND tab.PERIOD_NAME <= #{periodNameTo}
and tab.COMPANY_ID = #{companyId}

mapper.update:
UPDATE gld_lon_contract_fin_cost cfc SET cfc.finance_income_includ=#{financeIncomeInclud},
cfc.finance_cost= ROUND(#{financeIncomeInclud}/ ( SELECT nvl(lcq.tax_rate,0)+1 FROM lon_contract_quotation lcq WHERE lcq.withdraw_id=cfc.withdraw_id),2),
cfc.finance_income_vat=#{financeIncomeInclud}-ROUND(#{financeIncomeInclud}/ ( SELECT nvl(lcq.tax_rate,0)+1 FROM lon_contract_quotation lcq WHERE lcq.withdraw_id=cfc.withdraw_id),2) WHERE cfc.finance_cost_id=#{financeCostId}

mapper.select:
select * from (select fc.period_name, lc.contract_name, lcw.withdraw_number, fc.cf_item, (select i.description from hls_cashflow_item i where i.cf_item = fc.cf_item and i.cf_type = 70) cf_item_n, fc.finance_cost, fc.start_date, fc.end_date, (select fc.currency_name from fnd_currency fc where fc.currency_code = lc.currency) currency_n, fc.post_flag , (select tt.meaning from sys_code_value_b_v tt where tt.code = 'cld.post_flag' and tt.code_value = nvl(fc.post_flag,'n')) post_flag_n from gld_lon_contract_fin_cost fc, lon_contract_withdraw lcw, lon_contract lc where lcw.withdraw_id = fc.withdraw_id and lc.contract_id = lcw.contract_id) tab
1=1
and tab.withdraw_number like concat('%', concat(#{withdrawNumber,jdbcType=VARCHAR}, '%'))
and tab.post_flag = #{postFlag}
and tab.period_name = #{periodName}

select * from gld_lon_contract_fin_cost fc
where fc.withdraw_id = #{withdrawId}
and fc.contract_id = #{contractId}
and fc.period_name = #{periodName}
and fc.cf_item is null

SELECT * FROM ( SELECT ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = lc.credit_bp_id ) credit_bp_name, lc.contract_number, lc.contract_name, lcw.withdraw_number, ( SELECT fc.company_full_name FROM fnd_company fc WHERE fc.company_id = lc.lon_company_id ) company_full_name, lcw.due_amount, lcw.due_date, cfc.start_date, cfc.end_date, cfc.finance_cost, cfc.cf_item, cfc.finance_cost_id, ( SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = cfc.cf_item ) cf_item_n, ifnull ( cfc.pre_post_flag, 'N' ) pre_post_flag, ifnull ( cfc.post_flag, 'N' ) post_flag, cfc.period_name, lc.currency, ( SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = lc.currency ) currency_n, lc.contract_finance_type FROM gld_lon_contract_fin_cost cfc, lon_contract lc, lon_contract_withdraw lcw WHERE cfc.contract_id = lc.contract_id AND cfc.withdraw_id = lcw.withdraw_id order by cfc.period_name asc) t1
1=1
and t1.credit_bp_name like concat(concat('%',#{creditBpName}),'%')
and t1.company_full_name like concat(concat('%',#{companyFullName}),'%')
and t1.contract_number like concat(concat('%',#{contractNumber}),'%')
and t1.withdraw_number like concat(concat('%',#{withdrawNumber}),'%')
and t1.post_flag = #{postFlag}
and (t1.period_name = #{periodName} or (t1.period_name < #{periodName} and t1.post_flag = 'N'))
and t1.start_date >= #{startDate}
and t1.end_date <= #{endDate}
